Context Debounce Reason Client filter 0–150ms optional Instant feel on small sets Server search 300ms Reduce API load Command palette 0ms Local filter of static actions <pre><code>// hooks/use-debounced-value.ts (target)
export function useDebouncedValue&lt;T&gt;(value: T, delay = 300): T {
  const [debounced, setDebounced] = useState(value);
  useEffect(() =&gt; {
    const id = setTimeout(() =&gt; setDebounced(value), delay);
    return () =&gt; clearTimeout(id);
  }, [value, delay]);
  return debounced;
}
</code></pre>

