Piece Path Provider <code>components/providers/app-providers.tsx</code> — <code>&lt;Toaster /&gt;</code> Hook <code>hooks/use-toast.ts</code> Underlying <code>sonner</code> <pre><code>// hooks/use-toast.ts (pattern)
import { toast as sonnerToast } from "sonner";

export function toast({
  title,
  description,
  variant = "default",
}: ToastOptions) {
  if (variant === "destructive") {
    return sonnerToast.error(title, { description });
  }
  return sonnerToast.success(title, { description });
}
</code></pre>

